    { "whistle_sync",     "bool",   true,        "Свист (отвлечение) слышат другие игроки; свист клиента отвлекает зомби. Навык проверяет только тот, кто свистит" },
    { "shot_sounds",      "bool",   true,        "Звук чужих выстрелов: звук оружия (из его BP_WeaponsPickupComponent) там, где пришёл MC_WeaponEffects; хост пересылает дальние выстрелы (120–350 м)" },
    { "mirror_sounds",    "bool",   false,       "Запасной путь: хост пересылает клиентам звуки предметов игроков сообщением SND" },
    { "sound_range_guard", "bool", true, "Звуки другого игрока, у которых в игре нет затухания с расстоянием (фонарик, еда и питьё, шприц, досылание патронов, выстрел и перезарядка арбалета, выстрел ракетницы, револьвер с глушителем), слышны только рядом с ним — с затуханием, которое игра даёт таким же звукам; раньше их было слышно по всей карте" },
    { "melee_client_hits", "bool",  true,        "Обычный удар холодным оружием клиента: попадание определяет сам клиент, урон наносит хост игровыми HitBody/HitHead (на хосте копия удара по движущимся зомби промахивалась)" },
    { "reload_loop_fix",  "bool",   true,        "Перезарядка по одному патрону (охотничья винтовка, Мосин, дробовики, Winchester, револьвер, гранатомёт): когда игрок закончил перезарядку, у других игроков его анимация тоже останавливается (раньше крутилась бесконечно)" },
    { "reload_cap_fix",   "bool",   true,        "Перезарядка по одному патрону останавливается на ёмкости оружия (раньше у клиента из-за задержки сети обрез набивался десятками патронов). Клиент: каждый вставленный патрон сразу учитывается на его экране, не дожидаясь ответа хоста, — игра сама останавливает перезарядку на полном магазине при любом пинге. Хост: никогда не держит в оружии больше ёмкости — лишний патрон возвращает в стопку патронов игрока (если некуда — кладёт ему под ноги); оружие, уже заряженное сверх ёмкости, исправляется при следующей перезарядке" },
    { "geiger_own_only",  "bool",   true,        "Дозиметр: каждый слышит только свой счётчик Гейгера (хост больше не слышит дозиметр клиента, клиент слышит свой)" },
    { "radiation_exit_sync", "bool", true,       "Хост: клиент вышел из радиационной зоны — его радиация перестаёт расти (раньше таймер зоны продолжал работать на хосте)" },
    { "fix_client_damage", "bool",  true,        "Хост: урон, падение урона с дистанцией и сила (нож) оружия клиентов считаются по их собственным характеристикам" },
    { "coop_slowtime_off", "bool", true,  "Кооператив: настройка игры «Замедление времени» (инвентарь, радиальное меню) выключается, пока подключены другие игроки, и возвращается после" },
    { "relay_skill_xp",    "bool", true,  "Хост: опыт навыков, который игра начисляет только на сервере (меткость, стойкость, первая помощь, выносливость), и сброс навыков после смерти получает сам клиент" },
    { "stealth_sync",        "bool", true,       "Скрытность клиента: зомби слышат шаги клиента не громче, чем их считает игра у самого клиента (присед, бег, навык «Скрытность»)" },
    { "stealth_trace",       "bool", false,      "Отладка, хост: писать в лог, каким чувством (зрение или слух) и с какого расстояния зомби заметил игрока" },
    { "shot_noise",          "bool", true,       "Зомби слышат выстрелы клиента: хост сообщает ИИ шум каждого выстрела клиента так же, как игра делает это для стрелка (радиус звука оружия, глушитель и дульный тормоз — как посчитала игра у самого клиента); раньше выстрелы клиента зомби не слышали" },
    { "weapon_pose_fix",     "bool", true,       "Хост: поза оружия других игроков как в одиночной игре — хост исправляет состояние боя (оружие в руках, прицеливание), которое игра клиента отправляет до смены слота, и передаёт остальным прицеливание ножом и ADS клиента" },
    { "client_weapon_stats", "bool", false, "Хост: характеристики оружия клиента брать из его отчёта, а не из записи предмета на хосте (запасной путь)" },
    { "host_weapon_fx_quiet", "bool", true, "Хост: эффекты оружия клиента (тряска камеры при выстреле и ударе) хост не повторяет — клиент делает их сам" },
    { "client_quiet_others", "bool", true,       "Клиент: чужие персонажи не действуют на вас через «игрока 0» (тряска камеры от чужого прицеливания и ножа, чужие болезни, чужой опыт)" },
    { "game_ui_input", "bool", true, "Клиент: окна игры (инвентарь, торговля, ящики) сохраняют курсор и управление мышью: ни мод, ни поздние события игры (конец разговора с торговцем) не возвращают управление камерой, пока окно открыто" },
    { "notes_relay", "bool", true, "Хост и клиент: уведомления игры о действии клиента, которые игра выполняет на хосте (фильтр противогаза, «рано спать», точка возрождения, деньги торговца, генератор, колодец, ключ-карта ангара и т. п.), показываются на экране этого клиента — текстом и значком самой игры" },
    { "notes_owner_only", "bool", true, "Хост и клиент: уведомление игры о действии другого игрока (клиент набрал воду из колодца, ударил гнездо, мод применяет состояние хоста) убирается с экрана того, кто этого не делал" },
    { "player_event_notes", "bool", true, "Уведомления о других игроках в стиле уведомлений игры: «<имя> погиб» и «<имя> возродился» (без причины смерти). Их видят все, кроме самого игрока; не чаще одного раза в 30 с на игрока. Решает хост; у клиента выключение только скрывает их на его экране. О подключении и отключении игроков сообщается как раньше" },
    { "turret_sync",      "bool", true,        "Турели лагерей и построенные игроками: выстрелы, наведение, отключение, урон и здоровье турелей хоста видны клиентам; отключение турели и попадания клиента доходят до хоста. Решает хост" },
    { "redirect_player0", "bool",   true,       "Хост: игровая логика клиента («игрок 0» в BP) работает с персонажем клиента, а не хоста (переломы, голод, уведомления)" },
    { "client_cvars",     "string", "",          "Консольные переменные, которые клиент выполняет при подключении, через ';'" },
    { "host_difficulty_sync", "bool", true,      "Хост: настройки сложности, которые игра считает на машине самого игрока, у клиентов как у хоста — множитель опыта, время обыска, износ оружия и глушителей, осечки, режим «только в голову», рюкзак в рюкзаке, продажа торговцам, карта без GPS. Свои значения клиента возвращаются, когда он выходит (и при следующем запуске игры, если она закрылась во время игры). Выкл = только карта без GPS, как раньше" },
    { "move_response_interval", "string", "0",  "Отладка: минимальный интервал (с) между ответами сервера на движение клиента; 0 = как в движке" },
    { "replicate_items",  "bool",   true,        "Предметы (надетые, выброшенные, лут) — сетевые объекты хоста; локальный лут клиента убирается" },
    { "prevent_client_loot", "bool", true, "Клиент: случайные спавнеры лута на вашей копии уровня не создают свой лут — лут приходит от хоста (иначе рядом с предметами хоста появлялись лишние); при выключении лишний лут удаляется уже после появления, как раньше" },
    { "craft_one_at_a_time", "bool", true,       "Клиент: крафт по одному предмету — следующий запрос уходит после ответа хоста, «скрафтить N» делается по одному (иначе хост списывал компоненты один раз, а предметы создавал все; компоненты у клиента зависали)" },
    { "medical_host_cure",   "bool", true,       "Хост: бинт/аптечка/лекарство другого игрока снимает кровотечение, перелом и инфекцию и на копии персонажа у хоста; кровотечение и перелом других игроков проходят сами и на хосте (иначе кровотечение продолжало отнимать здоровье)" },
    { "client_infection_hud", "bool", true,      "Полоса заражения у клиента (тёмная плашка с полосой и значком вируса слева посередине экрана после укуса зомби): игра показывала её только хосту; хост сообщает клиенту, заражён ли его персонаж и на сколько процентов" },
    { "item_gains_from_host", "bool", true,      "Предметы, которые игра выдаёт при использовании (тряпки при разрывании одежды, пустая банка/бутылка, наполненная бутылка, содержимое коробки), добавляет хост; «мигающая» локальная заготовка у клиента убирается (иначе предмет был только у клиента и мигал)" },
    { "craft_needs_components", "bool", true,    "Крафт клиента должен быть оплачен предметами, которые есть у хоста: иначе клиент его не отправляет, а хост забирает созданный предмет (раньше «предмет-призрак» у клиента позволял крафтить бесконечно)" },
    { "menu_key",         "string", "F7",        "Клавиша меню (имя из таблицы Key UE4SS)" },
    { "client_cheats",    "bool",   true,        "Хост: клиенты могут пользоваться отладочным меню и читами игры (Debug.Allow: выдача предметов и опыта, неуязвимость, полёт сквозь стены, без голода, жажды и усталости). Выкл. = мод клиента держит их выключенными, пока клиент в вашем мире, и возвращает его настройки после (обойти можно только изменённым модом)" },
    { "friendly_fire",    "bool",   false,       "Хост: огонь по своим — игроки могут ранить друг друга (пули, удары, топот, гранаты, снаряды гранатомёта и ракетомёта, огонь коктейля Молотова). Выкл. = хост гасит такой урон: зомби, люди, звери, падение, ловушки, бочки и турели ранят как обычно, своя граната и свой огонь — тоже. Игроки получают уведомление о смене правила; клиентам ставить не нужно — решает хост" },
    { "down_enabled",     "bool",   false,       "Хост: нокдаун и подъём напарником. Смертельный удар не убивает сразу, если в мире есть кому помочь (игрок с этой версией мода): игрок садится на землю на down_bleedout_s секунд, напарник поднимает его — смотрит на него и держит клавишу взаимодействия (F) 5 секунд; здоровье после подъёма — как до удара, но от 10 до 25. Лежащего не бьют зомби и не ранят игроки; сдаться — держать F 3 секунды. Голод, жажда, радиация, утопление и инфекция убивают как обычно. В одиночной игре не действует; клиентам ставить не нужно — решает хост" },
    { "down_bleedout_s",  "int",    60,          "Хост: сколько секунд раненый игрок лежит, прежде чем умрёт (нокдаун — down_enabled; от 15 до 300)" },
    { "banned_players",   "string", "",          "Хост: забаненные игроки через ';' — SteamID (можно с именем: SteamID:Имя) или имя. Кнопка «Бан» в списке игроков добавляет игрока сюда; снять бан можно на вкладке «Мир» панели кооператива" },
    { "join_access",      "string", "open",      "Хост: кто может войти в ваш мир — open (все), password (по паролю: игроки из allowed_players входят сразу, остальные — и по IP, и через Steam — вводят join_password), approve (игроки из allowed_players входят сразу, остальных вы впускаете на вкладке «Мир» панели кооператива; без ответа 2 минуты — отказ) или list (только приглашённые: только игроки из allowed_players; «Пригласить» на вкладке «Steam» добавляет друга туда)" },
    { "join_password",    "string", "",          "Хост: пароль для входа при join_access = password; задаётся на вкладке «Мир». Верный пароль добавляет игрока в allowed_players. Хранится здесь открытым текстом — не используйте пароль от Steam, почты и т.п." },
    { "allowed_players",  "string", "",          "Хост: список допущенных игроков через ';' — SteamID (можно с именем: SteamID:Имя) или имя. «Пустить» на вкладке «Мир» добавляет игрока сюда" },
    { "max_players",      "int",    0,           "Хост: сколько игроков может быть в мире одновременно, считая вас; 0 = без ограничения. В заполненный мир новых игроков не пускают" },
    { "players_hud",      "bool",   true,        "Таблица игроков в правом верхнем углу во время игры: кто в мире и пинг (хост видит пинг каждого клиента, клиент — свой пинг до хоста). Показать и скрыть — клавишей players_hud_key (F8)" },
    { "players_hud_key",  "string", "F8",        "Клавиша, которая показывает и скрывает таблицу игроков (имя из таблицы Key UE4SS)" },
    { "chat",             "bool",   true,        "Текстовый чат в кооперативе: Enter открывает строку внизу слева, Enter отправляет, Esc закрывает. Выкл. = вы не видите сообщений и не можете писать; хост при этом всё равно пересылает сообщения остальным" },
    { "chat_sound",       "bool",   true,        "Тихий щелчок, когда приходит сообщение другого игрока (не чаще раза в 3 секунды)" },
    { "chat_key",         "string", "Enter",     "Клавиша, которая открывает чат, по имени клавиши Unreal: Enter, Slash… (не те имена, что у menu_key; не клавиша vehicle_seat_key, G). Отправка всегда Enter, закрытие — Esc" },
    { "lobby",            "bool",   true,        "Страницы кооператива в меню игры (главное меню и пауза)" },
    { "menu_in_main_menu","bool",   true,       "Панель кооператива открывается сама в главном меню. Действует только без кнопки «Кооператив» в меню игры (lobby = false): с кнопкой панель открывается ею" },
    { "join_cover",       "bool",   true,        "Клиент: пока вы подключаетесь к другу, экран закрыт тёмной заставкой с ходом подключения (связь с хостом, загрузка мира, персонаж, вещи и место) — пока ваш персонаж не встанет туда, где вы вышли (вида из-под земли не видно). Не дольше минуты в мире хоста; клавиша меню (F7) или Esc сразу показывает игру" },
    { "language",         "string", "auto",      "Язык панели и сообщений мода: auto (язык игры, а если в игре нет русского — язык Windows; кнопка «Кооператив» в меню игры — на языке игры), ru или en" },
    { "ui_open_at_menu",  "bool",   false,       "Тест: панель кооператива открывается сама в главном меню (для снимков экрана; вкладку выбирает Mods/SDCoop/ui_test.txt)" },
    { "quest_dialogues", "bool", true, "Разговор с NPC (торговцы, выдача заданий) открывается у того, кто заговорил, а не у хоста" },
    { "quest_hud",       "bool", true, "Клиент: окно диалогов и уведомлений о заданиях (интерфейс Narrative игры); без него диалоги остаются у хоста" },
    { "quest_vendor_fallback", "bool", true, "Клиент: если после диалога окно торговли не открылось само, открыть его по сигналу хоста" },
    { "trade_host_traders", "bool", true, "Клиент: военный торговец и торговец «Shakes & Cones» — только торговцы хоста; свою копию (её создаёт спавнер на вашей копии уровня) клиент не создаёт и убирает: хост о ней не знает, и торговать с ней нельзя" },
    { "trade_vendor_money", "bool", true, "Деньги торговца в окне торговли у клиента — как у хоста: хост присылает их в начале разговора и после каждой сделки (в игре они не передаются по сети, и у клиента было своё случайное число)" },
    { "quest_trace",     "bool", true, "Отладка: строки dlg-trace в UE4SS.log — где и для кого запускаются диалоги NPC" },
    { "quest_own",       "bool", true, "Хост: задания у каждого игрока свои, как в одиночной игре — клиент берёт задания у NPC (разведданные за деньги, зоны, стартовое), выполняет их и получает опыт сам; задание живёт в журнале клиента. Выключено — старый режим «общий журнал хоста» (настройки ниже про задания группы действуют только в нём)" },
    { "quest_bounty_shared", "bool", true, "Задания с ноутбуков (разведданные) общие: остаётся в журнале того, кто купил, но метка, задание в трекере и опыт за выполнение — у всех игроков; врагов может убивать любой, «дойти до места» засчитывается любому (при своих заданиях у каждого)" },
    { "quest_sync",      "bool", true, "Клиент видит задания группы (журнал хоста): уведомления о новых заданиях и прогрессе" },
    { "quest_tracker",   "bool", true, "Показывать задания группы в трекере заданий игры (панель «задание обновлено»)" },
    { "quest_datatask",  "bool", true, "Действия клиента для заданий (генератор лаборатории) засчитываются в задания группы" },
    { "quest_goto",      "bool", true, "Задание «дойти до места» выполняется, когда туда дошёл любой игрок" },
    { "quest_crate",     "bool", true, "Засекреченный ящик, открытый клиентом, открывается и у хоста (прогресс задания, награда)" },
    { "quest_markers",   "bool", true, "Метки заданий группы на карте и компасе клиента" },
    { "quest_xp",        "bool", true, "Опыт за выполненное задание группы получает и каждый клиент" },
    { "diag_snapshots",   "int",    30,          "Отладка: раз в N секунд писать в лог снимок состояния (персонаж, здоровье, HUD, управление, пинг, зомби рядом) и сразу — пропажу персонажа/HUD/управления; 0 = выкл" },
    { "gap_trace",        "bool",   false,       "Отладка: считать, что игра делает для каждого игрока (Mods/SDCoop/gaptrace_<роль>.csv, сравнение — tools/gapdiff.py)" },
    { "listen_ip_fallback", "bool", true,       "Перед подключением по IP переключить сетевой драйвер игры на обычные UDP-сокеты (порт 7777), если мод ещё не сделал этого при запуске (через них работают и Steam-подключение через помощник, и IP)" },
