local SPEC = {}
for _, s in ipairs(SCHEMA) do SPEC[s[1]] = s end
M.SCHEMA = SCHEMA   -- read-only use: sdc_i18n (settings labels / descriptions)

-- A number setting's value from text: a number as such, else the first
-- whole number in it ("30 %" / "30%" -> 30, "250 zombies" -> 250, "1,5" ->
-- 1); nil when there is none ("abc", empty).
local function to_int(raw)
    local n = tonumber(raw)
    if not n then
        local num = tostring(raw or ""):match("%-?%d+")
        n = num and tonumber(num)
    end
    return n and math.floor(n) or nil
end

local function coerce(kind, raw, default)
    if kind == "bool" then
        local v = tostring(raw):lower()
        if v == "1" or v == "true" or v == "yes" or v == "on" then return true end
        if v == "0" or v == "false" or v == "no" or v == "off" then return false end
        return default
    elseif kind == "int" then
        local n = to_int(raw)
        if n then return n end
        return default
    end
    return tostring(raw)
end

function M.get(key)
    local v = M.values[key]
    if v == nil and SPEC[key] then return SPEC[key][3] end
    return v
end

-- false: a number setting given text with no number in it ("abc", empty -
-- the panel's box): its value stays as it is (on loading: the default).
function M.set(key, value)
    local s = SPEC[key]
    if not s then return end
    if s[2] == "int" and to_int(value) == nil then return false end
    M.values[key] = coerce(s[2], value, s[3])
    return true
end

-- "bool" | "int" | "string" of a setting (nil: no such setting).
function M.kind(key)
    local s = SPEC[key]
    return s and s[2] or nil
end

function M.player_name()
    local n = M.get("player_name")
    if n and n ~= "" then return n end
    -- the Steam name the Steam link helper reported (sdc_steamlink requires this module, so no require here)
    local sl = package.loaded["sdc_steamlink"]
    local sn = sl and type(sl.persona) == "function" and sl.persona() or nil
    if type(sn) == "string" and sn ~= "" then return sn end
    local u = os.getenv("USERNAME")
    if u and u ~= "" then return u end
    return "Player"
end

local function trim(s) return (s:gsub("^%s+", ""):gsub("%s+$", "")) end

function M.load(path)
    M.path = path
    for _, s in ipairs(SCHEMA) do M.values[s[1]] = s[3] end
    local f = path and io.open(path, "r")
    if not f then
        log.info("config: %s not found, writing defaults", tostring(path))
        M.save()
        return
    end
    for line in f:lines() do
        line = line:gsub("\r$", "")
        if not line:match("^%s*[#;]") then
            local k, v = line:match("^%s*([%w_]+)%s*=%s*(.-)%s*$")
            if k and SPEC[k] then M.set(k, trim(v)) end
        end
    end
    f:close()
    log.debug_enabled = M.get("debug") == true
    log.probes_enabled = M.get("debug_probes") == true
    log.net_enabled = M.get("debug_net") == true
    log.flush_ms = M.get("log_flush_ms")
    log.batch_always = M.get("log_batch_always") == true
    log.info("config loaded from %s", path)
end

function M.save()
    if not M.path then return false end
    local f, err = io.open(M.path, "w")
    if not f then
        log.err("config: cannot write %s: %s", tostring(M.path), tostring(err))
        return false
    end
    f:write("# SDCoop settings. Меняются из игрового меню (F7) или вручную при закрытой игре.\n")
    for _, s in ipairs(SCHEMA) do
        local v = M.values[s[1]]
        if v == nil then v = s[3] end
        f:write(string.format("\n# %s\n%s = %s\n", s[4], s[1], tostring(v)))
    end
    f:close()
    log.debug_enabled = M.get("debug") == true
    log.probes_enabled = M.get("debug_probes") == true
    log.net_enabled = M.get("debug_net") == true
    log.flush_ms = M.get("log_flush_ms")
    log.batch_always = M.get("log_batch_always") == true
    return true
end

return M
